    async markNotificationRead(notificationId) {
        if (!notificationId) return null;
        const request = {
            path: PRIVATE_POST_NOTIFICATION_READ,
            body: {
                notification_id: notificationId,
            },
        }
        const resp = await this.sendToNode(request);

        // Optimistic local update so the SideNav badge ticks down
        // without waiting for the next poll. Flip the matching
        // notification's is_read and decrement unread_count.
        const target = latestNotifications.notifications.find(n => n && n.id === notificationId);
        if (target && !target.is_read) {
            target.is_read = true;
            latestNotifications = {
                unread_count: Math.max(0, (latestNotifications.unread_count || 1) - 1),
                notifications: latestNotifications.notifications,
            };
            for (const cb of notificationSubscribers) {
                cb(latestNotifications);
            }
        }
        return resp;
    },

    // markAllNotificationsRead flips every unread notification on the node
    // in one request. Marking page-by-page from the client only ever
    // covered the first page, so unread items beyond it kept the badge
    // alive forever.
    async markAllNotificationsRead() {
        const resp = await this.sendToNode({
            path: PRIVATE_POST_NOTIFICATIONS_READ,
            body: {},
        });

        // Optimistic local update so the SideNav badge clears without
        // waiting for the next poll.
        latestNotifications = {
            unread_count: 0,
            notifications: latestNotifications.notifications.map(
                n => n && !n.is_read ? { ...n, is_read: true } : n
            ),
        };
        for (const cb of notificationSubscribers) {
            cb(latestNotifications);
        }
        return resp;
    },

    async markMessageNotificationsRead() {
        const items = (latestNotifications.notifications || [])
            .filter(n => n && n.type === 'message' && !n.is_read);
        await Promise.all(items.map(n => this.markNotificationRead(n.id).catch(() => {})));
    },

    subscribeNotifications(callback) {
        notificationSubscribers.add(callback);
        callback(latestNotifications);
        return () => {
            notificationSubscribers.delete(callback);
        };
    },

    async getTweets({userId,cursorReset}) {
        let cursor = this.getCursor('tweets')
        if (cursorReset) {
            cursor = ''
        }
        if (cursor === endCursor) {
            return []
        }

        const request = {
            path: PUBLIC_GET_TWEETS,
            body: {
                limit: defaultLimit,
                cursor: cursor,
                user_id: userId,
            },
        }

        const tweetsResp = await this.sendToNode(request);
        if (!tweetsResp) {
            return []
        }
        this.setCursor('tweets', tweetsResp.cursor || 'end')
        if (!tweetsResp.tweets || tweetsResp.tweets.length === 0) {
            return []
        }

        return tweetsResp.tweets;
    },

    // Explicit-cursor page fetch for one user's tweets. Unlike getTweets it
    // never touches the global 'tweets' cursor, so many per-user paginations
    // (the unified timeline fans out per followed fediverse handle) can run
    // side by side without clobbering the Profile view.
    async getUserTweetsPage({userId, cursor = '', limit = defaultLimit}) {
        if (cursor === endCursor) {
            return {tweets: [], cursor: endCursor};
        }
        const resp = await this.sendToNode({
            path: PUBLIC_GET_TWEETS,
            body: {limit, cursor, user_id: userId},
        });
        // sendToNode maps an error body to {} — distinguish that from a
        // legitimate empty page so a flaky gateway reads as "failed"
        // (retryable), not "exhausted".
        if (!resp || (resp.tweets === undefined && resp.cursor === undefined)) {
            throw new Error(`no tweets response for ${userId}`);
        }
        return {tweets: resp.tweets || [], cursor: resp.cursor || endCursor};
    },

    // price is in the wallet token's base units.
    async createTweet({text, imageKeys, videoKey, poll, price}) {
        const owner = this.getOwnerProfile()

        const request ={
            path: price ? PRIVATE_POST_SPONSORED_TWEET : PRIVATE_POST_TWEET,
            body: {
                user_id: owner.user_id,
                username: owner.username,
                text: text,
                image_keys: imageKeys || [],
                created_at: new Date().toISOString(),
            },
        }
        if (videoKey) {
            request.body.video_key = videoKey;
        }
        if (poll) {
            request.body.poll = {
                options: poll.options,
                expires_at: poll.expiresAt,
            };
        }
        if (price) {
            request.body.price = {units: Number(price)};
        }

        const resp = await this.sendToNode(request);
        // sendToNode resolves on a node error too, and the composer would
        // then drop a draft that was never posted.
        if (price && (!resp || resp.code || !resp.id)) {
            throw new Error("Your node can't publish sponsored tweets yet.");
        }
        return resp;
    },

